DROP TABLE IF EXISTS `delivery_batches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `delivery_batches` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `submitted_by_user_id` int(10) unsigned NOT NULL,
  `delivery_date` date NOT NULL COMMENT 'business date for this delivery run',
  `submitted_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_delivery_date` (`delivery_date`),
  KEY `idx_submitted` (`submitted_at`),
  KEY `fk_batch_user` (`submitted_by_user_id`),
  CONSTRAINT `fk_batch_user` FOREIGN KEY (`submitted_by_user_id`) REFERENCES `app_users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

