--
-- Table structure for table `rts_cases`
--

DROP TABLE IF EXISTS `rts_cases`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `rts_cases` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `tracking_number` varchar(96) NOT NULL,
  `courier_detected` varchar(16) DEFAULT NULL COMMENT 'spx|jnt|flash|unknown',
  `courier_final` varchar(16) NOT NULL,
  `shop` varchar(24) NOT NULL COMMENT 'shopee|lazada|tiktok|vip',
  `vip_subsource` varchar(16) DEFAULT NULL COMMENT 'website|facebook when shop=vip',
  `date_delivered` date DEFAULT NULL,
  `date_opened` date NOT NULL COMMENT 'parcel opened / recorded',
  `documentation_photo` varchar(190) DEFAULT NULL COMMENT 'filename in assets/rts_documentation',
  `documentation_attachments` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '[{kind:image|video,file:name}]' CHECK (json_valid(`documentation_attachments`)),
  `damaged_reason` enum('leak','item_replaced','packaging_replaced') DEFAULT NULL COMMENT 'NULL = not damaged',
  `damaged_tag` varchar(128) NOT NULL DEFAULT 'no' COMMENT 'no | yes - Leak etc.',
  `claim_status` enum('for_submission','denied_claims','approved_claims','submitted_claims','on_process') NOT NULL DEFAULT 'for_submission',
  `claim_status_note` varchar(512) NOT NULL DEFAULT '',
  `delivery_match_item_id` int(10) unsigned DEFAULT NULL COMMENT 'delivery_batch_items.id for before-delivery photo',
  `parcel_info_snapshot` text DEFAULT NULL COMMENT 'optional raw courier item text later',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `voided_at` datetime DEFAULT NULL COMMENT 'admin voided; row kept for audit',
  `voided_by_user_id` int(10) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_tracking` (`tracking_number`),
  KEY `idx_shop` (`shop`),
