--
-- Table structure for table `rts_line_items`
--

DROP TABLE IF EXISTS `rts_line_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `rts_line_items` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `case_id` int(10) unsigned NOT NULL,
  `product_type` varchar(32) NOT NULL COMMENT 'honey|honey_with_other|pouch_pt|pouch_pt_with_honey|pouch_brc|jar_cacao|jar_cacao_with_honey|jar_honey_comb',
  `honey_size` varchar(16) DEFAULT NULL COMMENT '250ml|350ml|liter|gallon',
  `honey_variant` varchar(16) DEFAULT NULL COMMENT 'light|amber|dark',
  `combo_product` varchar(32) DEFAULT NULL COMMENT 'slug of paired product in w/other combos',
  `combo_quantity` decimal(10,2) DEFAULT NULL COMMENT 'quantity of the combo product',
  `combo_honey_size` varchar(16) DEFAULT NULL COMMENT 'honey size when combo item IS honey',
  `combo_honey_variant` varchar(16) DEFAULT NULL COMMENT 'honey variant when combo item IS honey',
  `quantity` decimal(10,2) NOT NULL,
  `is_bonus` tinyint(1) NOT NULL DEFAULT 0,
  `bonus_parent_id` int(10) unsigned DEFAULT NULL COMMENT 'id of parent line if this is a bonus',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_case` (`case_id`),
  KEY `idx_bonus_parent` (`bonus_parent_id`),
  CONSTRAINT `fk_line_case` FOREIGN KEY (`case_id`) REFERENCES `rts_cases` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=745 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

