DROP TABLE IF EXISTS `sp_sort_batches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sp_sort_batches` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `submitted_by_user_id` int(10) unsigned NOT NULL,
  `label` varchar(120) DEFAULT NULL COMMENT 'optional batch name',
  `row_count` int(10) unsigned NOT NULL DEFAULT 0,
  `source_files` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'original upload filenames' CHECK (json_valid(`source_files`)),
  `print_meta` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'order/pickup date lines, notes' CHECK (json_valid(`print_meta`)),
  `prepared_by` varchar(120) DEFAULT NULL,
  `merged_filename` varchar(190) DEFAULT NULL COMMENT 'sorted xlsx in assets/sp_sort',
  `status` enum('in_progress','completed') NOT NULL DEFAULT 'in_progress',
  `completed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_sp_sort_status` (`status`),
  KEY `idx_sp_sort_created` (`created_at`),
  KEY `fk_sp_sort_user` (`submitted_by_user_id`),
  CONSTRAINT `fk_sp_sort_user` FOREIGN KEY (`submitted_by_user_id`) REFERENCES `app_users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
