  CONSTRAINT `fk_sp_sort_rows_batch` FOREIGN KEY (`batch_id`) REFERENCES `sp_sort_batches` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=287 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
